"""Build the Russian #577 report draft (bare semantic HTML with render-kit markers) from metrics.json. Prose follows ASD-STE100 rules in Russian."""
import json, sys, html
R = sys.argv[1]; m = json.load(open(f"{R}/metrics.json")); E = html.escape
def row(cells, th=False):
    t = "th" if th else "td"; return "<tr>" + "".join(f"<{t}>{c}</{t}>" for c in cells) + "</tr>"
arms = ["baseline", "scope"]; AR = {"baseline": "базовое", "scope": "кандидат"}
CAT = {"regression-insensitive": "тест не чувствует регрессию", "implementation-coupling": "тест привязан к реализации", "reimplemented-production-logic": "стаб переписывает правило production"}
PAIR = {"pair-2": "пара 2", "pair-3": "пара 3", "pair-4": "пара 4"}
hits = [row(["Пара", "Категория", "Плечо", "плохих раундов", "поисковик назвал", "в финале", "потеряно в конвейере", "починенных раундов", "ложных"], True)]
for pair, v in m["pairs"].items():
    for a in arms:
        s = v[a]; hits.append(row([PAIR[pair] if a == "baseline" else "", CAT[v["category"]] if a == "baseline" else "", AR[a], s["bad_rounds"], s["found_hits"], s["final_hits"], s["lost_in_pipeline"], s["repaired_rounds"], s["false_positives"]]))
tot = {a: {k: sum(v[a][k] for v in m["pairs"].values()) for k in ("bad_rounds", "found_hits", "final_hits", "repaired_rounds", "false_positives")} for a in arms}
for a in arms:
    t = tot[a]; hits.append(row(["<strong>все пары</strong>" if a == "baseline" else "", "", f"<strong>{AR[a]}</strong>", t["bad_rounds"], f"<strong>{t['found_hits']}</strong>", f"<strong>{t['final_hits']}</strong>", "", t["repaired_rounds"], f"<strong>{t['false_positives']}</strong>"]))
cost = [row(["Плечо", "Раундов", "Деградировало", "Токенов на раунд", "Claude на раунд", "Codex на раунд", "агент docs+tests на раунд", "Минут на раунд", "Находок в финале на раунд"], True)]
for a in arms:
    c = m["cost"][a]["total"]; n = c["rounds"]
    cost.append(row([AR[a], n, c["degraded"], f"{c['tokens']/n/1e6:.1f}M", f"{c['claude']/n/1e6:.1f}M", f"{c['codex']/n/1e6:.2f}M", f"{c['docs_tests']/n/1e6:.2f}M", f"{c['ms']/n/60000:.1f}", f"{c['final_findings']/n:.1f}"]))
LAB = {
 "pair-2": ("Тесты расширения Pi для brew требовали пустой список уведомлений после таймаута и после ненулевого кода команды. Тесты защищали молчание при сбое.", "Основание: PR #135 и его прогон, где 6 тестов упали на старом коде."),
 "pair-3": ("Тесты жизненного цикла herdr-child ждали исторический alias <code>orange-panda</code>. Ожидание шло из того же аллокатора, что и проверяемое значение.", "Основание: PR #167 и аудит в старом документе #249."),
 "pair-4": ("Стаб Herdr в <code>tests/helpers/herdr_task_sync.bash</code> принимал равный номер последовательности. Production его отвергает. Тесты принимали записи, которые production игнорирует.", "Основание: PR #115 и аудит в старом документе #249."),
}
labels = "".join(f"<dt>{PAIR[p]} · {CAT[m['pairs'][p]['category']]}</dt><dd>{LAB[p][0]} <small>{LAB[p][1]}</small></dd>" for p in m["pairs"])
notes = []; ST = {"bad": "плохой", "repaired": "починенный"}
for a in arms:
    for r in m["rows"][a]:
        tag = "<ins>попадание</ins>" if r.get("final_hit") else ("<mark>только поисковик</mark>" if r.get("found_hit") else ("<del>ложное</del>" if r.get("false_positive") else "<small>нет</small>"))
        notes.append(row([AR[a], PAIR[r["pair"]], ST[r["stage"]], r["task"].split("#")[1].replace("rep", ""), tag, E(r.get("note", ""))]))
page = f"""<!doctype html><html lang="ru"><head><title>Scope-инструкция для тест-дублей в revmux: измерение #577</title>
<!-- kit: head -->
<!-- kit: components -->
</head><body><main lang="ru">
<hgroup><h1>Помогает ли строка в scope «прочитай дубль и то, что он заменяет, рядом» видеть слабые тесты?</h1>
<p>Issue #577, кандидат 1 · базовое плечо: 18 раундов <code>lean</code> из измерения #249 · 29 октября 2026 · 18 новых раундов кандидата, слепая разметка под непрозрачными id</p></hgroup>
<nav aria-label="Содержание"><ul><li><a href="#q">Ответ</a></li><li><a href="#terms">Термины</a></li><li><a href="#setup">Условия</a></li><li><a href="#hits">Попадания и ложные</a></li><li><a href="#cost">Цена</a></li><li><a href="#notes">Вердикты по раундам</a></li><li><a href="#limits">Ограничения</a></li><li><a href="#next">Дальше</a></li></ul></nav>
<h2 id="q">Ответ</h2>
<p><del>Нет. Шаблон scope остаётся без изменений.</del> Строка scope, которая называет каждый тест-дубль и то, что он заменяет, не заставила ни одного поисковика открыть стаб и сравнить его с настоящим правилом. На трёх парах и девяти плохих раундах на плечо кандидат улучшил один вердикт и добавил два ложных. Цена выше на 13% токенов на раунд.</p>
<ul>
<li>Пара 2, тесты защищали молчание при сбое. Базовое плечо назвало дефект в 3 из 3 проходов поисковиков и в 2 из 3 финальных списков. Кандидат назвал его в 3 из 3 финальных списков. Это та же разница в один раунд, что дал блок линзы в #249. Пилот #408 показал шум повторов такого же размера.</li>
<li>Пара 3, тесты ждали исторический alias. Ни одно плечо не назвало размеченный дефект ни в одном раунде. В двух из трёх починенных раундов кандидат дал ту же находку, что блок линзы в #249: «ожидаемый alias берётся из вывода самого аллокатора». В #249 её давал агент <code>docs+tests</code>. Здесь её дали <code>bugs+impl</code> (minor) и <code>arch+quality</code> (major). Разметчик отверг её оба раза: стаб записывает аргумент, который <code>herdr-child</code> передал в <code>herdr agent start</code>. Ожидание наблюдается на границе стаба, а не выводится из аллокатора. Упоминание <code>herdr-aliases.sh</code> рядом со стабом привело двух поисковиков к этому выводу. Базовое плечо такой находки не дало.</li>
<li>Пара 4, стаб принимал то, что production отвергает. Ни один поисковик ни в одном плече не назвал дефект за шесть плохих раундов. Scope называл стаб и <code>herdr-task-sync</code> рядом. Строка, написанная для этого дефекта, его не показала.</li>
</ul>
<p>Issue допускает результат без изменений. Это такой результат. Измерен кандидат 1 из списка #577. Кандидаты 2 (отдельный агент для доказательств тестов) и 3 (правило стадии) не измерены.</p>
<h2 id="terms">Термины</h2>
<dl>
<dt>Плечо</dt><dd>Один вариант условий. Базовое плечо равно профилю <code>lean</code> без изменений и обычному scope. Кандидат равен тому же профилю плюс один раздел в scope.</dd>
<dt>Тест-дубль</dt><dd>Хелпер, фейк или стаб. Тесты запускают его вместо настоящей программы.</dd>
<dt>Пара</dt><dd>Два коммита одного дефекта. Плохой коммит внёс слабый тест. Починенный коммит исправил его.</dd>
<dt>Раунд</dt><dd>Один прогон revmux: одно плечо, один коммит, один повтор.</dd>
<dt>Попадание</dt><dd>Находка, которая называет тот же тест и ту же причину слабости, что и разметка. Попадание на уровне поисковика: любой кандидат от агентов. Попадание в финале: находка финального списка.</dd>
<dt>Ложное</dt><dd>Находка финального списка на починенном коммите, которая утверждает дефект, которого в коде нет.</dd>
</dl>
<h2 id="setup">Условия</h2>
<dl>
<dt>Базовое плечо</dt><dd>Профиль <code>lean</code>: пять поисковиков, три группы Claude opus 5.5 и две группы Codex gpt-6.1-sol. Синтез и проверка на opus:high. Это 18 раундов измерения #249 от 28 октября. Те же замороженные коммиты, тот же профиль, тот же revmux 0.2.7 и тот же служебный конфиг. Раунды не прогоняли заново. Между плечами два дня.</dd>
<dt>Кандидат</dt><dd>Тот же профиль. Текст промптов не менялся. В <code>scope.md</code> каждого раунда добавлен один раздел «Read in full, side by side». Раздел называет каждый тест-дубль, который дифф трогает или которым управляет, и то, что дубль заменяет. Пара 2: фейк <code>ui</code> для Pi и фейки команд рядом с вызовами в расширении. Пара 3: сгенерированные заменители <code>herdr</code> и <code>git</code> рядом с установленным CLI и их вызывающими скриптами. Пара 4: заменитель <code>herdr</code> и стаб модели рядом с установленным CLI и <code>herdr-task-sync</code>. Текст называет файлы и команды. Текст не говорит, что искать.</dd>
<dt>Кейсы</dt><dd>Три размеченные пары из диапазонов #249. Пара 1 корпуса исключена из-за размера. Кандидат прошёл каждый из шести коммитов три раза: 18 раундов. Ни один раунд не деградировал.</dd>
<dt>Разметка</dt><dd><dl>{labels}</dl></dd>
<dt>Разметчик</dt><dd>Один агент OpenCode gpt-5.6-terra на пару. Агент читал все двенадцать раундов пары под непрозрачными id: шесть базовых из #249 и шесть новых. Агент видел размеченный дефект и замороженный код. Для каждого раунда агент записал попадание на уровне поисковика, попадание в финале и ложные находки на починенных раундах. Агент не видел имена плеч.</dd>
</dl>
<h2 id="hits">Попадания и ложные</h2>
<table>{''.join(hits)}</table>
<p>Одно ложное базового плеча на паре 4 равно находке <code>lean-1</code> в третьем повторе починенного коммита: «регрессионная проверка равной последовательности не откалибрована на исходном дефекте». Разметчик #249 читал тот же раунд и ложное не засчитал. Этот разметчик засчитал. Базовые раунды таким образом судили дважды разные слепые агенты. 15 из 18 вердиктов совпали. Три расхождения: это ложное и два попадания на уровне поисковика, которые разметчик #249 записал на починенных раундах пары 3, а этот не записал. Только ложное меняет ячейку таблицы. Шум разметки равен одной ячейке на восемнадцать раундов.</p>
<h2 id="cost">Цена</h2>
<table>{''.join(cost)}</table>
<p>Рост цены идёт в основном от пары 3. Плохой коммит пары 3 стоил 12.9M токенов на раунд против 10.8M. Поисковики читали больше файлов. Вывод о размеченном тесте не изменился.</p>
<h2 id="notes">Вердикты по раундам</h2>
<details><summary>36 строк, одна на раунд, с фразой разметчика на английском</summary><table>{row(["Плечо","Пара","Коммит","Повтор","Итог","Заметка разметчика"], True)}{''.join(notes)}</table></details>
<h2 id="limits">Ограничения</h2>
<ul>
<li>Три пары, девять плохих раундов на плечо. Изменение scope, которое помогает одной категории из десяти, здесь не видно.</li>
<li>Базовое плечо не прогоняли заново. Модели за идентификаторами <code>opus</code> и <code>gpt-6.1-sol</code> те же. Состояние сервиса через два дня не контролируется.</li>
<li>Разметчик равен модели gpt-5.6-terra, effort high, один на пару. Он не видел плечо. Он видел стадию коммита, плохой или починенный.</li>
<li>Production-сторона стабов в парах 3 и 4 равна установленному бинарю <code>herdr</code>. Scope мог назвать только его <code>--help</code> и вызывающие скрипты, а не файл с правилом. Для пары 4 правило, которое стаб нарушил (равная последовательность отвергается), не записано и в <code>herdr pane report-metadata --help</code>. Поисковик, который прочитал всё названное, не имел с чем сравнить стаб. Это ограничение кандидата, а не только измерения.</li>
</ul>
<h2 id="next">Дальше</h2>
<ul>
<li>Записать результат без изменений на #577 и #249. Шаблон scope и профиль <code>lean</code> остаются как есть.</li>
<li>Два кандидата из списка #577 не измерены. Ограничение по паре 4 говорит в пользу правила стадии (кандидат 3) или брифа отдельного агента (кандидат 2). Правило должно спрашивать, где записано правило, которое стаб кодирует, и что происходит на граничном значении. Правило не должно просить прочитать больше файлов.</li>
<li>Повторное использование базового плеча работает. Те же 18 раундов, которые судили два разных разметчика, совпали в 15 вердиктах и во всех ячейках таблицы кроме одной. Следующее измерение на этих парах может снова взять их и потратить раунды на кандидата.</li>
</ul>
</main>
<!-- kit: scripts -->
</body></html>"""
open(f"{R}/draft-ru.html", "w").write(page); print("draft written", len(page))
